import './tokens.css';
export * from './components';
export * from './icons';
export * from './product-components';

'use client';

import {
  forwardRef,
  useEffect,
  useId,
  useRef,
  useState,
  type ButtonHTMLAttributes,
  type CSSProperties,
  type HTMLAttributes,
  type InputHTMLAttributes,
  type KeyboardEvent,
  type ReactNode,
} from 'react';
import './components.css';

const classes = (...values: Array<string | false | undefined>) => values.filter(Boolean).join(' ');

export type SurfaceMaterial = 'solid' | 'glass' | 'inset';
export interface GlassSurfaceProps extends HTMLAttributes<HTMLDivElement> {
  material?: SurfaceMaterial;
}

/** Glass is a presentation choice; it never implies a connected or running system. */
export const GlassSurface = forwardRef<HTMLDivElement, GlassSurfaceProps>(
  function GlassSurface({ material = 'solid', className, ...props }, ref) {
    return <div {...props} ref={ref} className={classes('sl-surface', `sl-surface--${material}`, className)} />;
  },
);

export interface StarlightButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'ghost';
  size?: 'sm' | 'md';
  loading?: boolean;
}

export const StarlightButton = forwardRef<HTMLButtonElement, StarlightButtonProps>(
  function StarlightButton({ variant = 'primary', size = 'md', loading = false, disabled, className, children, type = 'button', ...props }, ref) {
    return (
      <button {...props} ref={ref} type={type} disabled={disabled || loading} aria-busy={loading || undefined}
        className={classes('sl-button', `sl-button--${variant}`, `sl-button--${size}`, className)}>
        {loading && <span className="sl-button__spinner" aria-hidden="true" />}
        {children}
      </button>
    );
  },
);

export type AgentStatus = 'unknown' | 'idle' | 'running' | 'blocked' | 'complete';
const statusLabels: Record<AgentStatus, string> = {
  unknown: 'Unknown', idle: 'Idle', running: 'Running', blocked: 'Blocked', complete: 'Complete',
};

export function StatusBadge({ status = 'unknown', className, ...props }: HTMLAttributes<HTMLSpanElement> & { status?: AgentStatus }) {
  const safeStatus = Object.hasOwn(statusLabels, status) ? status : 'unknown';
  return (
    <span {...props} className={classes('sl-status', `sl-status--${safeStatus}`, className)}>
      <span className="sl-status__dot" aria-hidden="true" />{statusLabels[safeStatus]}
    </span>
  );
}

export interface AgentPresenceProps extends HTMLAttributes<HTMLDivElement> {
  roleId: string;
  name: string;
  role: string;
  status?: AgentStatus;
  description?: string;
}

/** The role ID is stable. A display name is presentation, never a runtime identifier. */
export function AgentPresence({ roleId, name, role, status = 'unknown', description, className, ...props }: AgentPresenceProps) {
  return (
    <div {...props} className={classes('sl-presence', className)}>
      <span className="sl-presence__avatar" aria-hidden="true"><span /><i /></span>
      <div className="sl-presence__body">
        <div className="sl-presence__heading"><strong>{name}</strong><StatusBadge status={status} /></div>
        <span className="sl-presence__role">{role}</span>
        <code className="sl-presence__id">{roleId}</code>
        {description && <p className="sl-presence__description">{description}</p>}
      </div>
    </div>
  );
}

export interface EvidenceDisclosureProps extends Omit<HTMLAttributes<HTMLDetailsElement>, 'title'> {
  summary: ReactNode;
  open?: boolean;
}

export function EvidenceDisclosure({ summary, children, className, ...props }: EvidenceDisclosureProps) {
  return (
    <details {...props} className={classes('sl-evidence', className)}>
      <summary><span>{summary}</span><span className="sl-evidence__marker" aria-hidden="true">+</span></summary>
      <div className="sl-evidence__content">{children}</div>
    </details>
  );
}

export interface TextFieldProps extends InputHTMLAttributes<HTMLInputElement> {
  label: string;
  hint?: string;
  error?: string;
}

export const TextField = forwardRef<HTMLInputElement, TextFieldProps>(
  function TextField({ label, hint, error, id: providedId, className, 'aria-describedby': describedBy, ...props }, ref) {
    const generatedId = useId();
    const id = providedId || generatedId;
    const description = [describedBy, hint && `${id}-hint`, error && `${id}-error`].filter(Boolean).join(' ') || undefined;
    return (
      <div className="sl-field">
        <label className="sl-field__label" htmlFor={id}>{label}{props.required && <span aria-hidden="true"> *</span>}</label>
        <input {...props} ref={ref} id={id} className={classes('sl-input', className)} aria-invalid={error ? true : props['aria-invalid']} aria-describedby={description} />
        {hint && <p className="sl-field__hint" id={`${id}-hint`}>{hint}</p>}
        {error && <p className="sl-field__error" role="alert" id={`${id}-error`}>{error}</p>}
      </div>
    );
  },
);

export interface ToggleProps extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, 'onChange' | 'aria-pressed'> {
  pressed: boolean;
  onPressedChange: (pressed: boolean) => void;
}

export const Toggle = forwardRef<HTMLButtonElement, ToggleProps>(
  function Toggle({ pressed, onPressedChange, onClick, children, className, type = 'button', ...props }, ref) {
    return (
      <button {...props} ref={ref} type={type} className={classes('sl-toggle', className)} aria-pressed={pressed}
        onClick={event => { onClick?.(event); if (!event.defaultPrevented) onPressedChange(!pressed); }}>
        <span className="sl-toggle__track" aria-hidden="true"><span /></span>{children}
      </button>
    );
  },
);

export interface TabItem { id: string; label: string; content: ReactNode }
export interface TabsProps {
  items: TabItem[];
  label: string;
  defaultValue?: string;
  value?: string;
  onValueChange?: (value: string) => void;
  className?: string;
}

/** Automatic activation: ArrowLeft/Right, Home and End move focus and selection. */
export function Tabs({ items, label, defaultValue, value, onValueChange, className }: TabsProps) {
  const id = useId();
  const [internalValue, setInternalValue] = useState(defaultValue ?? items[0]?.id);
  const buttons = useRef<Array<HTMLButtonElement | null>>([]);
  const requestedValue = value ?? internalValue;
  const selected = items.some(item => item.id === requestedValue) ? requestedValue : items[0]?.id;
  function select(next: string) {
    if (value === undefined) setInternalValue(next);
    onValueChange?.(next);
  }
  function navigate(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    const last = items.length - 1;
    const next = event.key === 'ArrowRight' ? (index + 1) % items.length
      : event.key === 'ArrowLeft' ? (index + last) % items.length
      : event.key === 'Home' ? 0 : event.key === 'End' ? last : undefined;
    if (next === undefined) return;
    event.preventDefault();
    select(items[next].id);
    buttons.current[next]?.focus();
  }
  if (!items.length) return null;
  return (
    <div className={classes('sl-tabs', className)}>
      <div className="sl-tabs__list" role="tablist" aria-label={label}>
        {items.map((item, index) => (
          <button key={item.id} ref={element => { buttons.current[index] = element; }} className="sl-tabs__tab" type="button"
            id={`${id}-tab-${index}`} role="tab" aria-selected={selected === item.id} aria-controls={`${id}-panel-${index}`}
            tabIndex={selected === item.id ? 0 : -1} onClick={() => select(item.id)} onKeyDown={event => navigate(event, index)}>{item.label}</button>
        ))}
      </div>
      {items.map((item, index) => (
        <div key={item.id} className="sl-tabs__panel" id={`${id}-panel-${index}`} role="tabpanel"
          aria-labelledby={`${id}-tab-${index}`} tabIndex={0} hidden={selected !== item.id}>{item.content}</div>
      ))}
    </div>
  );
}

export interface CommandItem { id: string; label: string; description?: string; onSelect: () => void }
export interface CommandPanelProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title?: string;
  items: CommandItem[];
}

/** Native dialog supplies modal semantics and focus containment; actions remain explicit. */
export function CommandPanel({ open, onOpenChange, title = 'Find a component', items }: CommandPanelProps) {
  const id = useId();
  const dialog = useRef<HTMLDialogElement>(null);
  const search = useRef<HTMLInputElement>(null);
  const previousFocus = useRef<HTMLElement | null>(null);
  const [query, setQuery] = useState('');
  const onOpenChangeRef = useRef(onOpenChange);
  onOpenChangeRef.current = onOpenChange;
  useEffect(() => {
    const element = dialog.current;
    if (!element) return;
    if (open && !element.open) {
      previousFocus.current = document.activeElement instanceof HTMLElement ? document.activeElement : null;
      setQuery('');
      element.showModal();
      search.current?.focus();
    } else if (!open && element.open) {
      element.close();
      if (previousFocus.current?.isConnected) previousFocus.current.focus();
      else document.querySelector<HTMLElement>('main[tabindex]')?.focus();
    }
  }, [open]);
  useEffect(() => {
    const element = dialog.current;
    return () => {
      // The native dialog leaves the top layer when removed. Deferring the
      // focus check avoids moving focus during React's development replay.
      queueMicrotask(() => {
        if (element && !element.isConnected) previousFocus.current?.focus();
      });
    };
  }, []);
  const filtered = items.filter(item => `${item.label} ${item.description || ''}`.toLowerCase().includes(query.toLowerCase().trim()));
  function handleKeyboard(event: KeyboardEvent<HTMLDialogElement>) {
    if (event.key === 'Escape') {
      event.preventDefault();
      event.stopPropagation();
      onOpenChange(false);
      return;
    }
    if (event.key === 'Tab') {
      const actions = Array.from(dialog.current?.querySelectorAll<HTMLElement>('button,input,select,textarea,a[href],[tabindex]') ?? [])
        .filter(element => element.tabIndex >= 0 && !element.matches(':disabled,[hidden]') && !element.closest('[inert]') && element.getClientRects().length > 0);
      const first = actions[0], last = actions.at(-1);
      if (!first || !last) { event.preventDefault(); dialog.current?.focus(); return; }
      // Keep keyboard traversal in the modal even when the browser's native
      // dialog traversal would move to browser chrome at the last control.
      if (event.shiftKey && (document.activeElement === first || !dialog.current?.contains(document.activeElement))) {
        event.preventDefault(); last.focus();
      } else if (!event.shiftKey && (document.activeElement === last || !dialog.current?.contains(document.activeElement))) {
        event.preventDefault(); first.focus();
      }
      return;
    }
    if (event.key !== 'ArrowDown' && event.key !== 'ArrowUp') return;
    const actions = Array.from(dialog.current?.querySelectorAll<HTMLButtonElement>('[data-command-item]') ?? []);
    if (!actions.length) return;
    const active = actions.indexOf(document.activeElement as HTMLButtonElement);
    const next = active === -1 ? (event.key === 'ArrowDown' ? 0 : actions.length - 1)
      : (active + (event.key === 'ArrowDown' ? 1 : actions.length - 1)) % actions.length;
    event.preventDefault();
    actions[next].focus();
  }
  return (
    <dialog ref={dialog} className="sl-command" aria-labelledby={`${id}-title`} onKeyDown={handleKeyboard}
      onCancel={event => { event.preventDefault(); onOpenChange(false); }}
      onClose={() => onOpenChangeRef.current(false)}
      onClick={event => { if (event.target === dialog.current) { const bounds = dialog.current.getBoundingClientRect(); if (event.clientX < bounds.left || event.clientX > bounds.right || event.clientY < bounds.top || event.clientY > bounds.bottom) onOpenChange(false); } }}>
      <div className="sl-command__heading"><h2 id={`${id}-title`}>{title}</h2><StarlightButton variant="ghost" size="sm" onClick={() => onOpenChange(false)} aria-label="Close command panel">Esc</StarlightButton></div>
      <TextField ref={search} label="Search components" type="search" value={query} onChange={event => setQuery(event.target.value)} autoComplete="off" placeholder="Search by name or purpose…" />
      <p className="sl-sr-only" role="status">{filtered.length} {filtered.length === 1 ? 'result' : 'results'}</p>
      <ul className="sl-command__results">
        {filtered.map(item => <li key={item.id}><button type="button" data-command-item onClick={() => { onOpenChange(false); item.onSelect(); }}><span>{item.label}</span>{item.description && <small>{item.description}</small>}</button></li>)}
      </ul>
      {!filtered.length && <p className="sl-command__empty">No matching components. Try another name.</p>}
      <p className="sl-command__footer">Use ↑ ↓ to browse, Enter to select, Esc to close.</p>
    </dialog>
  );
}

export function EmptyState({ title, description, action, className, ...props }: HTMLAttributes<HTMLDivElement> & { title: string; description: string; action?: ReactNode }) {
  return <div {...props} className={classes('sl-empty', className)}><span className="sl-empty__mark" aria-hidden="true">∅</span><h3>{title}</h3><p>{description}</p>{action && <div className="sl-empty__action">{action}</div>}</div>;
}

export function Skeleton({ label = 'Loading content', className, style, ...props }: HTMLAttributes<HTMLDivElement> & { label?: string }) {
  return <div {...props} className={classes('sl-skeleton', className)} style={style} role="status"><span className="sl-sr-only">{label}</span></div>;
}

export interface ProgressMeterProps { value: number | null; max?: number; label: string; className?: string }
export function ProgressMeter({ value, max = 100, label, className }: ProgressMeterProps) {
  const id = useId();
  const safeMax = Number.isFinite(max) && max > 0 ? max : 100;
  const safeValue = value !== null && Number.isFinite(value) ? Math.min(safeMax, Math.max(0, value)) : undefined;
  const percent = safeValue === undefined ? null : Math.round(safeValue / safeMax * 100);
  return (
    <div className={classes('sl-progress', className)} style={{ '--sl-progress-value': `${percent ?? 0}%` } as CSSProperties}>
      <div className="sl-progress__heading"><label htmlFor={id}>{label}</label><span aria-hidden="true">{percent === null ? 'In progress' : `${percent}%`}</span></div>
      <progress id={id} value={safeValue} max={safeMax} />
    </div>
  );
}

/* Starlight Living Design · Original components. Token-first, framework-independent CSS. */
.sl-surface,.sl-button,.sl-status,.sl-presence,.sl-evidence,.sl-field,.sl-toggle,.sl-tabs,.sl-command,.sl-empty,.sl-skeleton,.sl-progress{box-sizing:border-box;color:var(--sl-text,#e8efef);font-family:inherit}
.sl-surface{position:relative;border:1px solid var(--sl-line,#354249);border-radius:var(--sl-radius-lg,24px);background:var(--sl-panel,#1a252d);isolation:isolate}
.sl-surface--glass{background:var(--sl-panel,#1a252d);box-shadow:inset 0 1px 0 rgb(255 255 255 / .08),var(--sl-shadow,0 20px 60px rgb(0 0 0 / .12))}
@supports(backdrop-filter:blur(1px)){.sl-surface--glass{background:var(--sl-glass,color-mix(in srgb,var(--sl-panel,#1a252d) 86%,transparent));backdrop-filter:blur(var(--sl-glass-blur,18px)) saturate(1.15);-webkit-backdrop-filter:blur(var(--sl-glass-blur,18px)) saturate(1.15)}}
.sl-surface--inset{background:var(--sl-bg,#101820);box-shadow:inset 0 1px 4px rgb(0 0 0 / .08)}
.sl-button{display:inline-flex;align-items:center;justify-content:center;gap:9px;min-height:44px;padding:0 18px;border:1px solid transparent;border-radius:var(--sl-radius-md,12px);font-size:13px;font-weight:600;letter-spacing:.01em;line-height:1.2;white-space:nowrap;cursor:pointer;transition:transform var(--sl-fast,140ms)}
.sl-button--primary{background:var(--sl-accent,#9bd8cd);color:var(--sl-accent-ink,#102a27)}
.sl-button--secondary{background:var(--sl-panel,#1a252d);border-color:var(--sl-line,#354249)}
.sl-button--ghost{background:transparent;border-color:transparent}
.sl-button--sm{min-height:44px;padding:0 12px;font-size:12px}
.sl-button:disabled{opacity:.48;cursor:not-allowed}
.sl-button:active:not(:disabled){transform:translateY(1px)}
.sl-button svg{width:17px;height:17px;flex:none}
.sl-button__spinner{width:13px;height:13px;border:1.5px solid currentColor;border-right-color:transparent;border-radius:50%;animation:sl-turn 700ms linear infinite}
.sl-status{display:inline-flex;align-items:center;gap:7px;width:max-content;max-width:100%;padding:5px 8px;border:1px solid var(--sl-line,#354249);border-radius:99px;background:var(--sl-panel,#1a252d);font-size:10px;font-weight:600;line-height:1.2;letter-spacing:.035em;white-space:nowrap}
.sl-status__dot{width:5px;height:5px;flex:none;border:1px solid currentColor;border-radius:50%}
.sl-status--unknown,.sl-status--idle{color:var(--sl-muted,#a7b8bf)}
.sl-status--running{color:var(--sl-accent,#9bd8cd)}
.sl-status--running .sl-status__dot{background:currentColor;box-shadow:0 0 0 3px color-mix(in srgb,currentColor 14%,transparent)}
.sl-status--blocked{color:var(--sl-danger,#ffaba7)}
.sl-status--blocked .sl-status__dot{border-radius:1px;transform:rotate(45deg);background:currentColor}
.sl-status--complete{color:var(--sl-success,#9fd4b8)}
.sl-status--complete .sl-status__dot{background:currentColor}
.sl-presence{display:flex;align-items:flex-start;gap:14px;min-width:0}
.sl-presence__avatar{position:relative;display:grid;place-items:center;width:49px;height:49px;flex:none;overflow:hidden;border:1px solid var(--sl-line,#354249);border-radius:16px;background:var(--sl-bg,#101820)}
.sl-presence__avatar>span{width:25px;height:25px;border:1px solid var(--sl-accent,#9bd8cd);border-radius:50%;transform:rotate(-32deg);box-shadow:inset 5px 0 0 color-mix(in srgb,var(--sl-accent,#9bd8cd) 20%,transparent)}
.sl-presence__avatar>i{position:absolute;width:31px;height:13px;border:1px solid var(--sl-muted,#a7b8bf);border-radius:50%;transform:rotate(-32deg)}
.sl-presence__body{flex:1;min-width:0}
.sl-presence__heading{display:flex;align-items:center;flex-wrap:wrap;gap:9px}
.sl-presence__heading>strong{font-size:14px;font-weight:600;letter-spacing:-.015em}
.sl-presence__role{display:block;margin-top:4px;color:var(--sl-muted,#a7b8bf);font-size:12px;line-height:1.4}
.sl-presence__id{display:block;overflow-wrap:anywhere;margin-top:6px;color:var(--sl-muted,#a7b8bf);font:10px/1.4 ui-monospace,SFMono-Regular,Consolas,monospace}
.sl-presence__description{margin:12px 0 0;color:var(--sl-muted,#a7b8bf);font-size:12px;line-height:1.6}
.sl-evidence{border-top:1px solid var(--sl-line,#354249);border-bottom:1px solid var(--sl-line,#354249)}
.sl-evidence>summary{display:flex;align-items:center;justify-content:space-between;gap:16px;min-height:48px;padding:12px 0;font-size:12px;font-weight:500;list-style:none;cursor:pointer}
.sl-evidence>summary::-webkit-details-marker{display:none}
.sl-evidence__marker{font-size:18px;font-weight:400;transition:transform var(--sl-fast,140ms)}
.sl-evidence[open] .sl-evidence__marker{transform:rotate(45deg)}
.sl-evidence__content{padding:0 0 17px;color:var(--sl-muted,#a7b8bf);font-size:12px;line-height:1.7;overflow-wrap:anywhere}
.sl-evidence__content>*:first-child{margin-top:0}.sl-evidence__content>*:last-child{margin-bottom:0}
.sl-evidence__content code{font-size:11px}
.sl-field{display:grid;gap:8px;min-width:0}
.sl-field__label{font-size:12px;font-weight:600;line-height:1.4}
.sl-input{box-sizing:border-box;width:100%;min-width:0;min-height:46px;padding:12px 14px;border:1px solid var(--sl-line,#354249);border-radius:var(--sl-radius-md,12px);background:var(--sl-bg,#101820);color:var(--sl-text,#e8efef);font:inherit;font-size:14px;line-height:1.4;transition:border-color var(--sl-fast,140ms),box-shadow var(--sl-fast,140ms)}
.sl-input::placeholder{color:var(--sl-muted,#a7b8bf);opacity:.8}
.sl-input:disabled{opacity:.5;cursor:not-allowed}
.sl-input[aria-invalid=true]{border-color:var(--sl-danger,#ffaba7)}
.sl-field__hint,.sl-field__error{margin:0;font-size:11px;line-height:1.5;color:var(--sl-muted,#a7b8bf)}
.sl-field__error{color:var(--sl-danger,#ffaba7)}
.sl-toggle{display:inline-flex;align-items:center;gap:10px;min-height:44px;padding:6px 0;border:0;background:transparent;text-align:left;font-size:12px;line-height:1.4;cursor:pointer}
.sl-toggle__track{display:flex;align-items:center;width:34px;height:20px;flex:none;padding:2px;border:1px solid var(--sl-line,#354249);border-radius:99px;background:var(--sl-bg,#101820);transition:background var(--sl-fast,140ms)}
.sl-toggle__track>span{width:14px;height:14px;border-radius:50%;background:var(--sl-muted,#a7b8bf);transition:transform var(--sl-fast,140ms),background var(--sl-fast,140ms)}
.sl-toggle[aria-pressed=true] .sl-toggle__track{background:var(--sl-accent,#9bd8cd);border-color:var(--sl-accent,#9bd8cd)}
.sl-toggle[aria-pressed=true] .sl-toggle__track>span{background:var(--sl-accent-ink,#102a27);transform:translateX(14px)}
.sl-toggle:disabled{opacity:.5;cursor:not-allowed}
.sl-tabs{min-width:0}.sl-tabs__list{display:flex;gap:4px;max-width:100%;overflow-x:auto;padding:4px;border:1px solid var(--sl-line,#354249);border-radius:var(--sl-radius-md,12px);background:var(--sl-bg,#101820)}
.sl-tabs__tab{flex:1;min-height:44px;min-width:max-content;padding:9px 14px;border:1px solid transparent;border-radius:8px;background:transparent;color:var(--sl-muted,#a7b8bf);font:inherit;font-size:12px;font-weight:500;cursor:pointer}
.sl-tabs__tab[aria-selected=true]{border-color:var(--sl-line,#354249);background:var(--sl-panel,#1a252d);color:var(--sl-text,#e8efef);box-shadow:0 2px 5px rgb(0 0 0 / .08)}
.sl-tabs__panel{padding-top:20px}.sl-tabs__panel[hidden]{display:none}
.sl-command{box-sizing:border-box;width:min(560px,calc(100vw - 32px));max-height:calc(100dvh - 64px);margin:auto;padding:24px;border:1px solid var(--sl-line,#354249);border-radius:var(--sl-radius-lg,24px);background:var(--sl-panel,#1a252d);color:var(--sl-text,#e8efef);box-shadow:0 32px 100px rgb(0 0 0 / .32);overflow-y:auto;overscroll-behavior:contain}
.sl-command::backdrop{background:rgb(4 12 18 / .68);backdrop-filter:blur(5px)}
.sl-command__heading{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:18px}
.sl-command__heading h2{margin:0;font-size:18px;font-weight:500;letter-spacing:-.03em}
.sl-command__results{display:grid;gap:4px;list-style:none;margin:16px 0 0;padding:0}
.sl-command__results button{display:flex;flex-direction:column;gap:5px;width:100%;min-height:52px;padding:12px;border:1px solid transparent;border-radius:10px;background:transparent;color:var(--sl-text,#e8efef);font:inherit;text-align:left;cursor:pointer}
.sl-command__results button span{font-size:13px;font-weight:500}.sl-command__results button small{font-size:11px;color:var(--sl-muted,#a7b8bf);line-height:1.5}
.sl-command__empty{padding:20px 0;color:var(--sl-muted,#a7b8bf);font-size:13px;text-align:center;line-height:1.6}
.sl-command__footer{margin:16px 0 0;padding-top:15px;border-top:1px solid var(--sl-line,#354249);color:var(--sl-muted,#a7b8bf);font-size:10px;line-height:1.5}
.sl-empty{display:flex;flex-direction:column;align-items:center;padding:28px 18px;text-align:center}
